  athlete: string;
  display?: string;
  garmin_account: string;
  protected?: number;
  /**
   * @minItems 1
   */
  actions: [
    {
      verb: "upload" | "replace" | "in_sync" | "move" | "schedule" | "unschedule";
      workout: string;
      key?: string;
      old_id?: number | null;
      workout_id?: number | null;
      dates?: string[];
      from?: string | null;
      to?: string | null;
    },
    ...{
      verb: "upload" | "replace" | "in_sync" | "move" | "schedule" | "unschedule";
      workout: string;
      key?: string;
      old_id?: number | null;
      workout_id?: number | null;
      dates?: string[];
      from?: string | null;
      to?: string | null;
    }[]
  ];
